const lum=f=>{const p=f.pixels;let sum=0;for(let i=0;i<p.length;i+=3)sum+=.2126*p[i]+.7152*p[i+1]+.0722*p[i+2];return sum/(p.length/3)/255};
const difference=(a,b)=>a.pixels.reduce((s,v,i)=>s+Math.abs(v-b.pixels[i]),0)/a.pixels.length/255;
export function detectTemporalEffects(samples){
 const f=samples.filter(x=>x.pixels?.length).sort((a,b)=>a.time-b.time),out=[];if(f.length<3)return out;const gaps=f.slice(1).map((x,i)=>x.time-f[i].time).filter(x=>x>0).sort((a,b)=>a-b),step=gaps[Math.floor(gaps.length/2)];if(!step)return out;
 const white=f.map(frame=>{let count=0;for(let j=0;j<frame.pixels.length;j+=3)if(Math.min(...frame.pixels.slice(j,j+3))>210)count++;return lum(frame)>.86&&count/(frame.pixels.length/3)>.75});
 for(let i=1;i<f.length-1;i++){if(!white[i])continue;const start=i;while(i+1<f.length&&white[i+1])i++;const end=i;if(end>=f.length-1)break;const a=f[start-1],c=f[end+1];if(c.time-a.time>.65||f[start].time-a.time>step*1.5||c.time-f[end].time>step*1.5)continue;if(Math.min(lum(f[start]),lum(f[end]))-Math.max(lum(a),lum(c))>.28)out.push({kind:'flash',start:a.time,end:c.time,title:'短暂白闪候选',reason:`${f[start].time.toFixed(2)}–${f[end].time.toFixed(2)} 秒的 ${end-start+1} 个采样中超过 75% 像素接近白色，前后亮度明显较低。也可能为现场闪光或白画面切换。`,parameters:`高亮采样点 ${f[start].time.toFixed(2)}–${f[end].time.toFixed(2)} 秒；边界精度不优于约 ${step.toFixed(2)} 秒`,steps:[`在 ${a.time.toFixed(2)}–${c.time.toFixed(2)} 秒附近新增白色素材并置于上层轨道。`,`逐帧找到原片白闪起止点，裁短白色素材；不透明度试做 0% → 100% → 0% 三个关键帧。`,'听原声核对是否有同步重音；实际强度、混合模式和原实现未知。']})}
 let start=null;const flush=end=>{if(start===null)return;if(end-start>=3&&f[end].time-f[start].time>=.5){const context=Math.max(1,Math.round(.25/step)),before=start>0?difference(f[Math.max(0,start-context)],f[start]):0,after=end<f.length-1?difference(f[end],f[Math.min(f.length-1,end+context)]):0;if(before>.01&&after>.01&&difference(f[start],f[end])<.003)out.push({kind:'freeze',start:f[start].time,end:f[end].time,title:'静止区间 / 定格候选',reason:`${end-start+1} 个连续采样的平均 RGB 差小于 0.2%，前后画面有变化。静态素材或固定画面也会产生同样结果。`,parameters:`连续相近画面 ${f[start].time.toFixed(2)}–${f[end].time.toFixed(2)} 秒；未证明使用了定格功能`,steps:[`在 ${f[start].time.toFixed(2)} 秒附近定位并选中视频，逐帧寻找真正停止运动的一帧。`,'使用“定格”（部分版本在片段右键菜单或基础编辑栏），生成静止片段。',`试将定格段长度设为约 ${(f[end].time-f[start].time).toFixed(2)} 秒，核对恢复运动的位置；原声可独立保留。`]})}start=null};for(let i=1;i<f.length;i++){const same=f[i].pixels.length===f[i-1].pixels.length&&f[i].time-f[i-1].time<=step*1.5&&difference(f[i-1],f[i])<.002;if(same){if(start===null)start=i-1}else flush(i-1)}flush(f.length-1);return out.sort((a,b)=>a.start-b.start)
}
